def can_segment_playlist(input_string, available_songs):
    dp = [False] * (len(input_string) + 1)
    dp[0] = True

    for i in range(1, len(input_string) + 1):
        for j in range(i):
            if dp[j] and input_string[j:i] in available_songs:
                dp[i] = True
                break

    return dp[len(input_string)]

def sort_transactions(stack):
    temp_stack = Stack()
    while not stack.isEmpty():
        current_transaction = stack.pop()
        while not temp_stack.isEmpty() and temp_stack.peek() < current_transaction:
            stack.push(temp_stack.pop())
        temp_stack.push(current_transaction)
    while not temp_stack.isEmpty():
        stack.push(temp_stack.pop())
    return stack
